const range=(k,label,min,max,step=1,unit='')=>`<label>${label} <output data-output="${k}"></output><input data-setting="${k}" type="range" min="${min}" max="${max}" step="${step}" data-unit="${unit}"></label>`;
const effects=['rgb','glitch','mirror','wave','mono','invert','mosaic','strobe','zoom','film'];
const fxControls=()=>`<section class="mosw"><h3>MOSW FX</h3><p>ENABLE UP TO 3 · DRAG TO REORDER</p><div id="fxList">${effects.map(name=>{const value=name==='mosaic'?12:35;return `<div class="fx-row" draggable="true" data-fx="${name}"><span class="handle">⋮⋮</span><label class="check"><input type="checkbox" data-fx-toggle="${name}"> ${name.toUpperCase()}</label><input aria-label="${name} amount" type="range" min="1" max="100" value="${value}" data-fx-param="${name}"><output data-fx-output="${name}">${value}</output></div>`}).join('')}</div><label>SYNC SOURCE<select id="syncSource"><option value="manual">MANUAL BPM</option><option value="mic">MIC INPUT</option></select></label>${range('bpm','BPM',40,240,1)}<p id="bpmStatus">SYNC: MANUAL</p></section>`;
const color=(k,label)=>`<label>${label}<input data-setting="${k}" type="color"></label>`;
const cubeFingers=()=>`<fieldset><legend>CUBE FINGERS</legend>${[['thumb','THUMB'],['index','INDEX'],['middle','MIDDLE'],['ring','RING'],['pinky','PINKY']].map(([value,label])=>`<label class="check"><input type="checkbox" data-cube-finger="${value}"> ${label}</label>`).join('')}</fieldset>`;
export function buildUI(){return `<main><section id="studio"><header><strong>HAND MOTION / <span id="status">STANDBY</span></strong><div><button id="startCamera">START CAMERA</button><button id="flip">CAMERA</button><button id="fullscreen">FULL</button><button id="shot">SHOT</button><button id="record">REC</button></div></header><div class="layout"><aside class="modes"><p>MODE SELECT</p>${[['cube','Hand Cube AR'],['invisible','Invisible'],['dissolve','Particle'],['frame','Hand Frame'],['volume','Hand Volume'],['anime','Anime Frame']].map(([v,n])=>`<button data-mode="${v}">${n}</button>`).join('')}</aside><section id="stage"><video id="camera" playsinline muted></video><canvas id="output"></canvas><canvas id="three"></canvas><canvas id="overlay"></canvas><div class="hint"><b id="gestureStatus">GESTURE: UNKNOWN</b><br/><span id="maskStatus">PERSON MASK: NOT READY</span><br/><span id="faceStatus">FACE LANDMARKER: IDLE</span><br/><span id="poseStatus">POSE: IDLE</span><br/><span id="throwStatus">THROW: READY</span><br/>INVISIBLE: OPEN WAVE / SALUTE</div></section><aside class="controls"><p>PARAMETERS</p><div data-mode-panel="cube">${cubeFingers()}${range('size','CUBE SIZE',.4,2,.1)}${range('cubeDistance','CUBE DISTANCE (APPROX. cm)',0,10,.5)}<label>FLOAT DIRECTION<select data-setting="floatDirection"><option value="camera">CAMERA</option><option value="up">UP</option><option value="outward">OUTWARD</option></select></label><label class="check"><input data-setting="cubeFloatDebug" type="checkbox"> FLOAT DEBUG</label>${range('speed','ROTATION',.1,3,.1)}${color('cubeColor','CUBE COLOR')}<label class="check"><input data-setting="throwEnabled" type="checkbox"> THROW</label>${range('throwSensitivity','THROW SENSITIVITY',.5,2,.1)}${range('gravity','GRAVITY',0,4,.1)}<label class="check"><input data-setting="throwDebug" type="checkbox"> THROW DEBUG</label></div><div data-mode-panel="invisible" hidden><p id="invisibleStatus">GESTURE: UNKNOWN · STATE: VISIBLE</p><p id="backgroundStatus">BACKGROUND: NOT CAPTURED</p><button id="capture">CAPTURE BACKGROUND</button><button id="clearBackground">CLEAR BACKGROUND</button><button id="maskDebug">MASK DEBUG: OFF</button>${range('gestureHold','GESTURE HOLD',200,1200,50,'ms')}${range('transitionDuration','TRANSITION',200,2000,50,'ms')}${range('edgeGlow','EDGE GLOW',0,30,1)}<label class="check"><input data-setting="invisibleDebug" type="checkbox"> INVISIBLE DEBUG</label></div><div data-mode-panel="dissolve" hidden><label>FLOW MODE<select data-setting="particleMode"><option value="classic">CLASSIC</option><option value="hand">HAND FLOW</option></select></label><label>PARTICLE SHAPE<select data-setting="particleShape"><option value="square">SQUARE ■</option><option value="circle">CIRCLE ●</option><option value="star">STAR ★</option><option value="mixed">MIXED</option></select></label><label>FLOW SOURCE<select data-setting="flowSource"><option value="auto">AUTO</option><option value="hand">HAND</option><option value="body">BODY</option></select></label>${range('particles','PARTICLE COUNT',50,1200,50)}${range('particleSize','PARTICLE SIZE',1,12,1)}${range('speed','PARTICLE SPEED',.1,3,.1)}${range('dispersion','DISPERSION',10,180,5)}${range('transitionDuration','TRANSITION',200,2000,50,'ms')}${range('flowStrength','FLOW STRENGTH',.1,5,.1)}${range('flowRadius','FLOW RADIUS',50,600,10)}${range('flowSmoothness','FLOW SMOOTHNESS',0,100,1)}${range('particleTrail','PARTICLE TRAIL',0,100,1)}${range('bodyWindStrength','BODY WIND STRENGTH',0,3,.1)}${range('bodyWindTurbulence','BODY WIND TURBULENCE',0,2,.1)}<label class="check"><input data-setting="handFlowDebug" type="checkbox"> HAND FLOW DEBUG</label>${color('particleColor','PARTICLE COLOR')}</div><div data-mode-panel="frame" hidden><p id="frameStatus">FRAME: LIVE</p><label class="check"><input data-setting="followRotation" type="checkbox"> FOLLOW ROTATION</label><label>RENDER MODE<select data-setting="frameRenderer"><option value="classic">CLASSIC</option><option value="mosw">MOSW FX</option></select></label><div data-frame-classic><label>PRESET<select data-setting="frameEffect"><option value="pop">NEON POP</option><option value="cmyk">CMYK</option><option value="mono">MONOCHROME</option><option value="pixel">CLASSIC PIXEL</option></select></label>${range('pixelSize','PIXEL SIZE',2,32,1)}</div><div data-frame-mosw hidden>${fxControls()}</div></div><div data-mode-panel="volume" hidden>${range('size','VOLUME SCALE',.4,2,.1)}${color('edgeColor','EDGE COLOR')}<label class="check"><input data-setting="throwEnabled" type="checkbox"> THROW</label>${range('throwSensitivity','THROW SENSITIVITY',.5,2,.1)}${range('gravity','GRAVITY',0,4,.1)}<label class="check"><input data-setting="throwDebug" type="checkbox"> THROW DEBUG</label></div><div data-mode-panel="anime" hidden>${range('posterize','COLOR LEVELS',2,10,1)}<label class="check"><input data-setting="faceEmoji" type="checkbox"> FACE EMOJI</label><label>EMOJI STYLE<select data-setting="emojiStyle"><option value="classic">CLASSIC</option><option value="pop">POP</option><option value="pixel">PIXEL</option></select></label>${range('emojiSize','EMOJI SIZE',.7,2,.05)}${range('expressionSensitivity','EXPRESSION SENSITIVITY',.5,2,.05)}${range('faceSmoothness','SMOOTHNESS',0,.95,.05)}<label class="check"><input data-setting="expressionDebug" type="checkbox"> SHOW EXPRESSION DEBUG</label></div><hr/><label class="check"><input data-setting="debug" type="checkbox"> LANDMARK DEBUG</label><label class="check"><input data-setting="mirror" type="checkbox"> MIRROR VIDEO</label><button id="reset">RESET SETTINGS</button><button id="export">EXPORT JSON</button><button id="import">IMPORT JSON</button><input id="importFile" type="file" accept="application/json" hidden/></aside></div><footer id="metrics">Camera FPS: 0 · Render FPS: 0 · MediaPipe FPS: 0</footer></section></main>`}
